<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/DB.php';require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Settings.php';require_once __DIR__.'/../core/PanTransfer.php';$limit=10;$ids=array();foreach(array_slice($argv,1)as $arg){if(preg_match('/^--limit=(\d+)$/',$arg,$m)){$limit=max(1,min(50,(int)$m[1]));}elseif(preg_match('/^--ids=(\d+(?:,\d+)*)$/',$arg,$m)){$ids=array_map('intval',explode(',',$m[1]));}}echo'['.date('Y-m-d H:i:s')."] pan_transfer start (limit={$limit}".($ids?' ids='.implode(',',$ids):'').")\n";try{$sum=\Core\PanTransfer::run($limit,$ids);}catch(\Throwable $e){echo'['.date('Y-m-d H:i:s')."] FATAL: ".$e->getMessage()."\n";exit(1);}echo'['.date('Y-m-d H:i:s')."] done: ok={$sum['ok']} fail={$sum['fail']} skip={$sum['skip']}\n";foreach($sum['details']as $d){echo'  #'.$d['item'].' ['.$d['pan'].'] '.$d['old'].($d['error']!==''?' -> 失败：'.$d['error']:' -> '.$d['new'])."\n";}